We obtain from the first equation: $\cos(x)\sin(y)+\sin(x)\cos(y) = -\cos(y)\sin(y) \Rightarrow \sin(x+y) = -\frac{\sin(2y)}{2} \Rightarrow x = -y-\arcsin\left[\frac{\sin(2y)}{2}\right]$  (i).

Substitution of (i) into the second equation yields: $\frac{\cos^{3}(y)}{\cos\left[y+\arcsin\left[\frac{\sin(2y)}{2}\right]\right]} - \frac{\sin^{3}(y)}{\sin\left[y+\arcsin\left[\frac{\sin(2y)}{2}\right]\right]} = 1$ ;

or  $\frac{\cos^{3}(y)} {\cos(y) \left(\frac{\sqrt{4-\sin^{2}(2y)} }{2}\right) - \sin(y)\left(\frac{\sin(2y)}{2}\right)}                    -                         \frac{\sin^{3}(y)}{  \sin(y) \left(\frac{\sqrt{4-\sin^{2}(2y)} }{2}\right) + \cos(y)\left(\frac{\sin(2y)}{2}\right)                                                                              } = 1$ ;

or  $\frac{\cos^{3}(y)} {\cos(y) \left(\frac{\sqrt{4-4\sin^{2}(y)\cos^{2}(y)} }{2}\right) - \sin(y)\left(\frac{2\sin(y)\cos(y)}{2}\right)}                    -                         \frac{\sin^{3}(y)}{  \sin(y) \left(\frac{\sqrt{4-4\sin^{2}(y)\cos^{2}(y)} }{2}\right) + \cos(y)\left(\frac{2\sin(y)\cos(y)}{2}\right)                                                                              } = 1$ ;

or  $\frac{\cos^{2}(y)} {\sqrt{1-\sin^{2}(y)\cos^{2}(y)} - \sin^{2}(y)}                    -                         \frac{\sin^{2}(y)}{  \sqrt{1-\sin^{2}(y)\cos^{2}(y)} + \cos^{2}(y)                                                                              } = 1$ ;

or  $\frac{\cos^{2}(y)[\sqrt{1-\sin^{2}(y)\cos^{2}(y)} + \cos^{2}(y)] - \sin^{2}(y)[\sqrt{1-\sin^{2}(y)\cos^{2}(y)} - \sin^{2}(y)]                               } {[\sqrt{1-\sin^{2}(y)\cos^{2}(y)} - \sin^{2}(y)][\sqrt{1-\sin^{2}(y)\cos^{2}(y)} + \cos^{2}(y)]                                                                              } = 1$ ;

or  $\frac{[\cos^{2}(y)-\sin^{2}(y)][\sqrt{1-\sin^{2}(y)\cos^{2}(y)} +\cos^{4}(y)+\sin^{4}(y)}{ [\cos^{2}(y)-\sin^{2}(y)][\sqrt{1-\sin^{2}(y)\cos^{2}(y)} + 1 - 2\sin^{2}(y)\cos^{2}(y)} = 1$ ;

or  $\frac{\cos(2y)\sqrt{1-\sin^{2}(y)\cos^{2}(y)} +\cos^{4}(y)+[1-\cos^{2}(y)]^2}{\cos(2y)\sqrt{1-\sin^{2}(y)\cos^{2}(y)}+ 1 - 2[1-\cos^{2}(y)]\cos^{2}(y)} = 1$ ;

or  $\frac{\cos(2y)\sqrt{1-\sin^{2}(y)\cos^{2}(y)} +[2\cos^{4}(y)-2\cos^{2}(y)+1]}{\cos(2y)\sqrt{1-\sin^{2}(y)\cos^{2}(y)} + [2\cos^{4}(y)-2\cos^{2}(y)+1]                             } = 1$ ;

or  $1 = 1$ .

QED

